BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='45s';
LOCK TABLE source_books IN SHARE MODE;
LOCK TABLE reading_source_bundles,mai_hoa_reading_templates,tam_the_supplement_results,tam_the_supplement_mappings IN SHARE ROW EXCLUSIVE MODE;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM flyway_schema_history WHERE version='12' AND success) THEN RAISE EXCEPTION 'M02 requires successful Flyway V12'; END IF; END $$;
DO $$ BEGIN IF (SELECT count(*) FROM source_books WHERE file_sha256='225e9506f4f7481e56618e3f46738467a64cf6231148c959664a23469faf22de' AND pdf_page_count=672) <> 1 THEN RAISE EXCEPTION 'M02 source PDF identity mismatch'; END IF; END $$;
DO $$ BEGIN IF (SELECT count(*) FROM source_books WHERE file_sha256='7976f690145cc0bbdf6cb1bf2a0276b843512d231dca9a9f83b6f99820816c7d' AND pdf_page_count=360) <> 1 THEN RAISE EXCEPTION 'M02 source PDF identity mismatch'; END IF; END $$;
CREATE TEMP TABLE expected_reading_source_bundles (LIKE reading_source_bundles INCLUDING DEFAULTS) ON COMMIT DROP;
CREATE TEMP TABLE expected_mai_hoa_reading_templates (LIKE mai_hoa_reading_templates INCLUDING DEFAULTS) ON COMMIT DROP;
CREATE TEMP TABLE expected_tam_the_supplement_results (LIKE tam_the_supplement_results INCLUDING DEFAULTS) ON COMMIT DROP;
CREATE TEMP TABLE expected_tam_the_supplement_mappings (LIKE tam_the_supplement_mappings INCLUDING DEFAULTS) ON COMMIT DROP;
DO $$ BEGIN
IF EXISTS (SELECT 1 FROM reading_source_bundles p WHERE p.bundle_id='M01-READINGS-20261026-V1'
   AND NOT EXISTS (SELECT 1 FROM expected_reading_source_bundles e WHERE to_jsonb(e)=to_jsonb(p)))
THEN RAISE EXCEPTION 'M02 changed/protected row in reading_source_bundles'; END IF;
IF EXISTS (SELECT 1 FROM reading_source_bundles WHERE bundle_id='M01-READINGS-20261026-V1')
   AND EXISTS ((SELECT * FROM expected_reading_source_bundles) EXCEPT (SELECT * FROM reading_source_bundles WHERE bundle_id='M01-READINGS-20261026-V1'))
THEN RAISE EXCEPTION 'M02 incomplete existing bundle in reading_source_bundles'; END IF;
END $$;
DO $$ BEGIN
IF EXISTS (SELECT 1 FROM mai_hoa_reading_templates p WHERE p.bundle_id='M01-READINGS-20261026-V1'
   AND NOT EXISTS (SELECT 1 FROM expected_mai_hoa_reading_templates e WHERE to_jsonb(e)=to_jsonb(p)))
THEN RAISE EXCEPTION 'M02 changed/protected row in mai_hoa_reading_templates'; END IF;
IF EXISTS (SELECT 1 FROM reading_source_bundles WHERE bundle_id='M01-READINGS-20261026-V1')
   AND EXISTS ((SELECT * FROM expected_mai_hoa_reading_templates) EXCEPT (SELECT * FROM mai_hoa_reading_templates WHERE bundle_id='M01-READINGS-20261026-V1'))
THEN RAISE EXCEPTION 'M02 incomplete existing bundle in mai_hoa_reading_templates'; END IF;
END $$;
DO $$ BEGIN
IF EXISTS (SELECT 1 FROM tam_the_supplement_results p WHERE p.bundle_id='M01-READINGS-20261026-V1'
   AND NOT EXISTS (SELECT 1 FROM expected_tam_the_supplement_results e WHERE to_jsonb(e)=to_jsonb(p)))
THEN RAISE EXCEPTION 'M02 changed/protected row in tam_the_supplement_results'; END IF;
IF EXISTS (SELECT 1 FROM reading_source_bundles WHERE bundle_id='M01-READINGS-20261026-V1')
   AND EXISTS ((SELECT * FROM expected_tam_the_supplement_results) EXCEPT (SELECT * FROM tam_the_supplement_results WHERE bundle_id='M01-READINGS-20261026-V1'))
THEN RAISE EXCEPTION 'M02 incomplete existing bundle in tam_the_supplement_results'; END IF;
END $$;
DO $$ BEGIN
IF EXISTS (SELECT 1 FROM tam_the_supplement_mappings p WHERE p.bundle_id='M01-READINGS-20261026-V1'
   AND NOT EXISTS (SELECT 1 FROM expected_tam_the_supplement_mappings e WHERE to_jsonb(e)=to_jsonb(p)))
THEN RAISE EXCEPTION 'M02 changed/protected row in tam_the_supplement_mappings'; END IF;
IF EXISTS (SELECT 1 FROM reading_source_bundles WHERE bundle_id='M01-READINGS-20261026-V1')
   AND EXISTS ((SELECT * FROM expected_tam_the_supplement_mappings) EXCEPT (SELECT * FROM tam_the_supplement_mappings WHERE bundle_id='M01-READINGS-20261026-V1'))
THEN RAISE EXCEPTION 'M02 incomplete existing bundle in tam_the_supplement_mappings'; END IF;
END $$;
DO $$ BEGIN
IF EXISTS ((SELECT * FROM expected_reading_source_bundles) EXCEPT (SELECT * FROM reading_source_bundles WHERE bundle_id='M01-READINGS-20261026-V1'))
 OR EXISTS ((SELECT * FROM reading_source_bundles WHERE bundle_id='M01-READINGS-20261026-V1') EXCEPT (SELECT * FROM expected_reading_source_bundles))
THEN RAISE EXCEPTION 'M02 final content/source/count mismatch in reading_source_bundles'; END IF;
END $$;
DO $$ BEGIN
IF EXISTS ((SELECT * FROM expected_mai_hoa_reading_templates) EXCEPT (SELECT * FROM mai_hoa_reading_templates WHERE bundle_id='M01-READINGS-20261026-V1'))
 OR EXISTS ((SELECT * FROM mai_hoa_reading_templates WHERE bundle_id='M01-READINGS-20261026-V1') EXCEPT (SELECT * FROM expected_mai_hoa_reading_templates))
THEN RAISE EXCEPTION 'M02 final content/source/count mismatch in mai_hoa_reading_templates'; END IF;
END $$;
DO $$ BEGIN
IF EXISTS ((SELECT * FROM expected_tam_the_supplement_results) EXCEPT (SELECT * FROM tam_the_supplement_results WHERE bundle_id='M01-READINGS-20261026-V1'))
 OR EXISTS ((SELECT * FROM tam_the_supplement_results WHERE bundle_id='M01-READINGS-20261026-V1') EXCEPT (SELECT * FROM expected_tam_the_supplement_results))
THEN RAISE EXCEPTION 'M02 final content/source/count mismatch in tam_the_supplement_results'; END IF;
END $$;
DO $$ BEGIN
IF EXISTS ((SELECT * FROM expected_tam_the_supplement_mappings) EXCEPT (SELECT * FROM tam_the_supplement_mappings WHERE bundle_id='M01-READINGS-20261026-V1'))
 OR EXISTS ((SELECT * FROM tam_the_supplement_mappings WHERE bundle_id='M01-READINGS-20261026-V1') EXCEPT (SELECT * FROM expected_tam_the_supplement_mappings))
THEN RAISE EXCEPTION 'M02 final content/source/count mismatch in tam_the_supplement_mappings'; END IF;
END $$;
COMMIT;
