INSERT INTO expected_reading_source_bundles VALUES ('M01-READINGS-20261026-V1','e3c460cdfe1a96546b243155205d12e8a27c1e45882452344a7dafa778e295b6','{"schemaVersion":1,"bundleId":"M01-READINGS-20261026-V1","task":"M01","scope":"Reviewed source content and explicit project conventions; importing does not enable runtime. Not 64 essays or 384 literal line judgments.","runtimeEnabled":false,"review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false},"books":{"MH":{"filename":"Mai hoa dich so-Thieu-khang Tiet.pdf","pages":672,"sha256":"225e9506f4f7481e56618e3f46738467a64cf6231148c959664a23469faf22de"},"TT":{"filename":"Diễn Cầm Tam Thế Diễn Nghĩa.pdf","pages":360,"sha256":"7976f690145cc0bbdf6cb1bf2a0276b843512d231dca9a9f83b6f99820816c7d"}},"sourceSurveySha256":"269fc5cbd3e8dca0812e9eb485233d493b89efd68ad00a96b966eeb934431457","decisions":[{"id":"DEC-20261026-M01-BODY","basis":"TEAM_DECISION","purpose":"CALCULATION","sourceStatus":"SOURCE_AMBIGUOUS","source":{"book":"MH","pdfPages":[224,225],"printedPages":[231,232]},"policy":"NON_MOVING_TRIGRAM_IS_BODY","detail":"Hào 1-3 động: Thể là thượng quái; hào 4-6 động: Thể là hạ quái. Dụng ở phía còn lại. Giữ Thể gốc khi so quái Dụng đã biến.","limitation":"Ví dụ Cách hỗ trợ trường hợp hào 1; chưa định vị câu tổng quát bao phủ sáu vị trí theo ấn bản. Không duyệt lại MH-THE-DUNG 1.0."},{"id":"DEC-20261026-M01-PHASES","basis":"TEAM_DECISION","purpose":"CALCULATION","sourceStatus":"SOURCE_AMBIGUOUS","source":{"book":"MH","pdfPages":[131,132,227,228],"printedPages":[137,138,234,235]},"policy":"ORIGINAL_BODY_SEPARATE_MUTUAL_SIDES","detail":"Đầu: Dụng gốc so Thể gốc. Giữa: cả hai quái hỗ so Thể gốc; cùng phía Thể mang vai trò BODY_MUTUAL. Cuối: quái ở phía Dụng trong quẻ biến so Thể gốc. Không cộng điểm hoặc gộp hai quan hệ giữa thành một kết luận.","limitation":"PDF228 mở đầu gọi hạ hỗ là hỗ Dụng rồi có trường hợp Thể dưới gọi hạ hỗ là hỗ Thể. Dùng quy ước vị trí công khai dựa nguyên văn PDF227; không sửa bản dịch."},{"id":"DEC-20261026-M01-SEASON","basis":"TEAM_DECISION","purpose":"CALCULATION","sourceStatus":"SOURCE_LOCATED","source":{"book":"MH","pdfPages":[131,133],"printedPages":[137,139]},"policy":"VIETNAM_LUNAR_MONTH_SEASON","detail":"Tháng âm 1,2: Xuân; 4,5: Hạ; 7,8: Thu; 10,11: Đông; 3,6,9,12: Thổ cuối mùa. Tháng nhuận giữ nhóm cùng số. TIME dùng datetime lập quẻ; LINES/OBJECT_COUNT chỉ dùng readingContext.datetime do người dùng cung cấp. Thiếu context: NOT_EVALUATED, vẫn có quan hệ và lời luận; không dùng thời gian máy.","limitation":"Quy đổi số tháng âm sang mùa là quy ước sản phẩm, chưa xác minh là thuật toán tiết khí của ấn bản. Không tính tiết khí hoặc 24 tiết bằng bảng này."},{"id":"DEC-20261026-M01-RELATIONS","basis":"SOURCE_VERIFIED","purpose":"INTERPRETATION","sourceStatus":"VERIFIED","source":{"book":"MH","pdfPages":[131,132,133,134,135],"printedPages":[137,138,139,140,141]},"policy":"DIRECTIONAL_FIVE_ELEMENT_RELATIONS","detail":"Duyệt riêng năm quan hệ: tỷ hòa, Dụng sinh Thể, Thể sinh Dụng, Thể khắc Dụng, Dụng khắc Thể. Dùng nguyên văn PDF132 và các mục chủ đề để phân biệt chiều.","limitation":"Không dùng câu PDF134 gọi hỗ/biến cùng hành Thể là đảng Dụng để tự tạo điểm số; không duyệt các ví dụ chi tiết ngoài phạm vi 20 đoạn."},{"id":"DEC-20261026-M01-SANG-HEN-LABELS","basis":"TEAM_DECISION","purpose":"EDITORIAL_LINK","sourceStatus":"SOURCE_AMBIGUOUS","source":{"book":"TT","pdfPages":[43,44],"printedPages":[44,45]},"policy":"PRESERVE_PRINTED_LABEL_LINK_BY_COLUMN","detail":"Cột 3 Hoa cái -> tiêu đề Hao Cái; cột 10 Vong sát -> Vong Thần; cột 11 Tướng linh -> Tướng Tinh; cột 12 Thiên an -> tiêu đề Phiên An (nội dung Thiên An). Giữ cả hai trường, liên kết theo thứ tự 12 đoạn.","limitation":"Đây là liên kết biên tập của dự án, không phải đính chính từ nhà xuất bản. Đoạn Hao Cái có token 3 và đoạn Tướng Tinh có chữ khó đọc: bản diễn giải chỉ giữ phần nghĩa đọc rõ."},{"id":"DEC-20261026-M01-DIEN-SAN-LABELS","basis":"TEAM_DECISION","purpose":"EDITORIAL_LINK","sourceStatus":"SOURCE_AMBIGUOUS","source":{"book":"TT","pdfPages":[49,50],"printedPages":[50,51]},"policy":"PRESERVE_PRINTED_LABEL_LINK_BY_COLUMN","detail":"Cột 6 bảng ghi Phú, đoạn thứ 6 ghi Phá; lưu nguyên cả hai và liên kết theo thứ tự cột. Chỉ gọi là Điền sản.","limitation":"Không sửa chữ Phú trên bản in và không coi nội dung Phá là lời giải tài lộc toàn diện."},{"id":"DEC-20261026-M01-DIEN-SAN-REFERENCE","basis":"TEAM_DECISION","purpose":"CALCULATION","sourceStatus":"SOURCE_AMBIGUOUS","source":{"book":"TT","pdfPages":[49],"printedPages":[50]},"policy":"REUSE_REVIEWED_YEAR_ELEMENT","detail":"Hướng dẫn in dẫn Số 6; dự án dùng hành mệnh đã duyệt ở TT-NGU-HANH/Số 4 làm khóa của bảng năm hành này.","limitation":"Tham chiếu Số 6 được bảo tồn; không coi quyết định nối dữ liệu là câu đã in ở Số 15."}],"maiHoaTemplates":[{"code":"MH-GENERAL-SAME_ELEMENT","topic":"GENERAL","relation":"SAME_ELEMENT","content":"Theo mục Thể–Dụng, hai quái cùng hành được xét là tỷ hòa, biểu thị sự hòa hợp trong quan hệ chủ–khách.","textKind":"EDITORIAL_PARAPHRASE","source":{"book":"MH","pdfPages":[132,135],"printedPages":[138,141]},"sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}},{"code":"MH-GENERAL-USE_GENERATES_BODY","topic":"GENERAL","relation":"USE_GENERATES_BODY","content":"Quái Dụng sinh cho quái Thể: mục nguồn diễn giải theo hướng chủ thể nhận được sự hỗ trợ hoặc lợi ích từ sự việc.","textKind":"EDITORIAL_PARAPHRASE","source":{"book":"MH","pdfPages":[132,135],"printedPages":[138,141]},"sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}},{"code":"MH-GENERAL-BODY_GENERATES_USE","topic":"GENERAL","relation":"BODY_GENERATES_USE","content":"Quái Thể sinh cho quái Dụng: mục nguồn coi đây là tiết khí, chủ thể phải bỏ sức hoặc hao tổn cho sự việc.","textKind":"EDITORIAL_PARAPHRASE","source":{"book":"MH","pdfPages":[132,135],"printedPages":[138,141]},"sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}},{"code":"MH-GENERAL-BODY_CONTROLS_USE","topic":"GENERAL","relation":"BODY_CONTROLS_USE","content":"Quái Thể khắc quái Dụng: theo quan hệ trong mục nguồn, chủ thể có thế chế ngự sự việc.","textKind":"EDITORIAL_PARAPHRASE","source":{"book":"MH","pdfPages":[132,135],"printedPages":[138,141]},"sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}},{"code":"MH-GENERAL-USE_CONTROLS_BODY","topic":"GENERAL","relation":"USE_CONTROLS_BODY","content":"Quái Dụng khắc quái Thể: theo mục nguồn, sự việc tạo sức ép hoặc trở ngại đối với chủ thể.","textKind":"EDITORIAL_PARAPHRASE","source":{"book":"MH","pdfPages":[132,135],"printedPages":[138,141]},"sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}},{"code":"MH-CAREER-SAME_ELEMENT","topic":"CAREER","relation":"SAME_ELEMENT","content":"Theo mục cầu danh, Thể–Dụng tỷ hòa được luận là công danh có sự thuận hợp.","textKind":"EDITORIAL_PARAPHRASE","source":{"book":"MH","pdfPages":[156,157],"printedPages":[162,163]},"sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}},{"code":"MH-CAREER-USE_GENERATES_BODY","topic":"CAREER","relation":"USE_GENERATES_BODY","content":"Theo mục cầu danh, Dụng sinh Thể được luận là dễ thành hoặc nhờ việc cầu danh mà có lợi ích.","textKind":"EDITORIAL_PARAPHRASE","source":{"book":"MH","pdfPages":[156,157],"printedPages":[162,163]},"sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}},{"code":"MH-CAREER-BODY_GENERATES_USE","topic":"CAREER","relation":"BODY_GENERATES_USE","content":"Theo mục cầu danh, Thể sinh Dụng được luận là khó đạt điều mong cầu hoặc có hao tổn danh lợi.","textKind":"EDITORIAL_PARAPHRASE","source":{"book":"MH","pdfPages":[156,157],"printedPages":[162,163]},"sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}},{"code":"MH-CAREER-BODY_CONTROLS_USE","topic":"CAREER","relation":"BODY_CONTROLS_USE","content":"Theo mục cầu danh, Thể khắc Dụng được luận là có thể thành nhưng tiến triển chậm.","textKind":"EDITORIAL_PARA