:"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}},{"code":"MH-WEALTH-BODY_GENERATES_USE","topic":"WEALTH","relation":"BODY_GENERATES_USE","content":"Theo mục cầu tài, Thể sinh Dụng được luận theo chiều hao tổn khi cầu tài.","textKind":"EDITORIAL_PARAPHRASE","source":{"book":"MH","pdfPages":[158],"printedPages":[164]},"sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}},{"code":"MH-WEALTH-BODY_CONTROLS_USE","topic":"WEALTH","relation":"BODY_CONTROLS_USE","content":"Theo mục cầu tài, Thể khắc Dụng được luận theo chiều có thể đạt điều cầu tài.","textKind":"EDITORIAL_PARAPHRASE","source":{"book":"MH","pdfPages":[158],"printedPages":[164]},"sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}},{"code":"MH-WEALTH-USE_CONTROLS_BODY","topic":"WEALTH","relation":"USE_CONTROLS_BODY","content":"Theo mục cầu tài, Dụng khắc Thể được luận theo chiều bất lợi đối với điều cầu tài.","textKind":"EDITORIAL_PARAPHRASE","source":{"book":"MH","pdfPages":[158],"printedPages":[164]},"sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}},{"code":"MH-LOVE-SAME_ELEMENT","topic":"LOVE","relation":"SAME_ELEMENT","content":"Theo mục hôn nhân, tỷ hòa được luận là hai bên thuận hợp.","textKind":"EDITORIAL_PARAPHRASE","source":{"book":"MH","pdfPages":[150,151],"printedPages":[156,157]},"sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}},{"code":"MH-LOVE-USE_GENERATES_BODY","topic":"LOVE","relation":"USE_GENERATES_BODY","content":"Theo mục hôn nhân, Dụng sinh Thể được luận là dễ thành hoặc có lợi ích từ quan hệ hôn nhân.","textKind":"EDITORIAL_PARAPHRASE","source":{"book":"MH","pdfPages":[150,151],"printedPages":[156,157]},"sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}},{"code":"MH-LOVE-BODY_GENERATES_USE","topic":"LOVE","relation":"BODY_GENERATES_USE","content":"Theo mục hôn nhân, Thể sinh Dụng được luận là khó thành hoặc có hao tổn trong việc hôn nhân.","textKind":"EDITORIAL_PARAPHRASE","source":{"book":"MH","pdfPages":[150,151],"printedPages":[156,157]},"sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}},{"code":"MH-LOVE-BODY_CONTROLS_USE","topic":"LOVE","relation":"BODY_CONTROLS_USE","content":"Theo mục hôn nhân, Thể khắc Dụng được luận là có thể thành nhưng chậm.","textKind":"EDITORIAL_PARAPHRASE","source":{"book":"MH","pdfPages":[150,151],"printedPages":[156,157]},"sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}},{"code":"MH-LOVE-USE_CONTROLS_BODY","topic":"LOVE","relation":"USE_CONTROLS_BODY","content":"Theo mục hôn nhân, Dụng khắc Thể được luận theo chiều bất lợi cho việc kết thành hôn nhân.","textKind":"EDITORIAL_PARAPHRASE","source":{"book":"MH","pdfPages":[150,151],"printedPages":[156,157]},"sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}}],"tamTheResults":[{"code":"TT-SANG-HEN-01","ruleCode":"TT-SANG-HEN","column":1,"title":"Nhựt Mã","tableLabel":"Nhựt mã","contentHeading":"Nhựt Mã","content":"Theo đoạn Nhựt Mã, sách mô tả người hay đi lại, làm ăn khá, có điền địa và tài lợi; ở nhà ít lo, ra ngoài được đối đãi trọng hậu.","textKind":"EDITORIAL_PARAPHRASE","sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","tableSource":{"book":"TT","pdfPages":[43],"printedPages":[44]},"contentSource":{"book":"TT","pdfPages":[43],"printedPages":[44]},"decisionIds":[],"review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}},{"code":"TT-SANG-HEN-02","ruleCode":"TT-SANG-HEN","column":2,"title":"Lục Hại","tableLabel":"Lục hại","contentHeading":"Lục Hại","content":"Theo đoạn Lục Hại, sách mô tả sự xung khắc với cha mẹ, anh em, họ hàng và vợ chồng con cái; đồng thời nêu hướng tu hành.","textKind":"EDITORIAL_PARAPHRASE","sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","tableSource":{"book":"TT","pdfPages":[43],"printedPages":[44]},"contentSource":{"book":"TT","pdfPages":[43],"printedPages":[44]},"decisionIds":[],"review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}},{"code":"TT-SANG-HEN-03","ruleCode":"TT-SANG-HEN","column":3,"title":"Hoa cái / Hao Cái","tableLabel":"Hoa cái","contentHeading":"Hao Cái","content":"Đoạn mang tiêu đề Hao Cái mô tả người có duyên, được nhiều người thương và kính trọng, có tài giỏi và lộc thực. Bản diễn giải không suy đoán token khó hiểu trong câu in.","textKind":"EDITORIAL_PARAPHRASE","sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","tableSource":{"book":"TT","pdfPages":[43],"printedPages":[44]},"contentSource":{"book":"TT","pdfPages":[44],"printedPages":[45]},"decisionIds":["DEC-20261026-M01-SANG-HEN-LABELS"],"review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}},{"code":"TT-SANG-HEN-04","ruleCode":"TT-SANG-HEN","column":4,"title":"Kiếp Sát","tableLabel":"Kiếp sát","contentHeading":"Kiếp Sát","content":"Theo đoạn Kiếp Sát, sách mô tả sự xung khắc trong gia đình, hoàn cảnh có thể sa sút; đoạn còn nêu phụ nữ thay đổi hôn nhân. Đây là mô tả trong nguồn cổ, không phải sự kiện đã được xác định cho người dùng.","textKind":"EDITORIAL_PARAPHRASE","sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","tableSource":{"book":"TT","pdfPages":[43],"printedPages":[44]},"contentSource":{"book":"TT","pdfPages":[44],"printedPages":[45]},"decisionIds":[],"review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}},{"code":"TT-SANG-HEN-05","ruleCode":"TT-SANG-HEN","column":5,"title":"Tai Sát","tableLabel":"Tai sát","contentHeading":"Tai Sát","content":"Theo đoạn Tai Sát, sách nêu tật bệnh, tai nạn và xung khắc vợ chồng, con cái. Nội dung được trình bày như quan niệm trong sách, không dùng để chẩn đoán bệnh hay xác nhận tai nạn.","textKind":"EDITORIAL_PARAPHRASE","sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","tableSource":{"book":"TT","pdfPages":[43],"printedPages":[44]},"contentSource":{"book":"TT","pdfPages":[44],"printedPages":[45]},"decisionIds":[],"review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}},{"code":"TT-SANG-HEN-06","ruleCode":"TT-SANG-HEN","column":6,"title":"Thiên Sát","tableLabel":"Thiên sát","contentHeading":"Thiên Sát","content":"Theo đoạn Thiên Sát, sách nêu xung khắc với gia đình bên vợ hoặc bên chồng, ít con, bệnh nặng hay cảnh lưu lạc tự tìm sinh kế. Các mô tả này thuộc lời luận của nguồn cổ.","textKind":"EDITORIAL_PARAPHRASE","sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","tableSource":{"book":"TT","pdfPages":[43],"printedPages":[44]},"contentSource":{"book":"TT","pdfPages":[44],"printedPages":[45]},"decisionIds":[],"review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}},{"code":"TT-SANG-HEN-07","ruleCode":"TT-SANG-HEN","column":7,"title":"Địa Sát","tableLabel":"Địa sát","contentHeading":"Địa Sát","content":"Theo đoạn Địa Sát, sách đồng thời nêu tai nạn, xung khắc trong gia đình và khả năng có nghề giỏi, làm ăn no đủ. Hai chiều nội dung được giữ cùng nhau.","textKind":"EDITORIAL_PARAPHRASE","sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","tableSource":{"book":"TT","pdfPages":[43],"printedPages":[44]},"contentSource":{"book":"TT","pdfPages":[44],"printedPages":[45]},"decisionIds":[],"review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}},{"code":"TT-SANG-HEN-08","ruleCode":"TT-SANG-HEN","column":8,"title":"Niên Sát","tableLabel":"Niên sát","contentHeading":"Niên Sát","content":"Theo đoạn Niên Sát, sách mô tả rời nơi cha mẹ đã lập để làm ăn nơi khác, tự tạo sự nghiệp, ít nhờ cậy anh em.","textKind":"EDITORIAL_PARAPHRASE","sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","tableSource":{"book":"TT","pdfPages":[43],"printedPages":[44]},"contentSource":{"book":"TT","pdfPages":[44],"printedPages":[45]},"decisionIds":[],"review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}},{"code":"TT-SANG-HEN-09","ruleCode":"TT-SANG-HEN","column":9,"title":"Ngoại Sát","tableLabel":"Ngoại sát","contentHeading":"Ngoại Sát","content":"Theo đoạn Ngoại Sát, sách mô tả làm ăn khá khi đến nơi khác, từ tay trắng lập sự nghiệp; đồng thời có lời luận xung khắc vợ chồng và con cái.","textKind":"EDITORIAL_PARAPHRASE","sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","tableSource":{"book":"TT","pdfPages":[43],"printedPages":[44]},"contentSource":{"book":"TT","pdfPages":[44],"printedPages":[45]},"decisionIds":[],"review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}},{"code":"TT-SANG-HEN-10","ruleCode":"TT-SANG-HEN","column":10,"title":"Vong sát / Vong Thần","tableLabel":"Vong sát","contentHeading":"Vong Thần","content":"Đoạn Vong Thần mô tả xung khắc anh em, bà con; qua nhiều lần đổi chỗ ở mới lập sự nghiệp, điền viên tốt. Nhãn bảng vẫn được lưu là Vong sát.","textKind":"EDITORIAL_PARAPHRASE","sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","tableSource":{"book":"TT","pdfPages":[43],"printedPages":[44]},"contentSource":{"book":"TT","pdfPages":[44],"printedPages":[45]},"decisionIds":["DEC-20261026-M01-SANG-HEN-LABELS"],"review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}},{"code":"TT-SANG-HEN-11","ruleCode":"TT-SANG-HEN","column":11,"title":"Tướng linh / Tướng Tinh","tableLabel":"Tướng linh","contentHeading":"Tướng Tinh","content":"Đoạn Tướng Tinh mô tả người có quyền hành, phát tài và hưởng lộc từ sớm, gia đình con cháu sung túc. Bản diễn giải chỉ giữ phần chữ đọc rõ, không đoán cụm chữ mờ sau quyền hành.","textKind":"EDITORIAL_PARAPHRASE","sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","tableSource":{"book":"TT","pdfPages":[43],"printedPages":[44]},"contentSource":{"book":"TT","pdfPages":[44],"printedPages":[45]},"decisionIds":["DEC-20261026-M01-SANG-HEN-LABELS"],"review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}},{"code":"TT-SANG-HEN-12","ruleCode":"TT-SANG-HEN","column":12,"title":"Thiên an / Phiên An","tableLabel":"Thiên an","contentHeading":"Phiên An","content":"Đoạn có tiêu đề Phiên An nhưng phần thân gọi Thiên An, mô tả tính cương cường, thông minh, có hướng tu niệm và học hành khoa cử. Dự án bảo tồn cả hai nhãn.","textKind":"EDITORIAL_PARAPHRASE","sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","tableSource":{"book":"TT","pdfPages":[43],"printedPages":[44]},"contentSource":{"book":"TT","pdfPages":[44],"printedPages":[45]},"decisionIds":["DEC-20261026-M01-SANG-HEN-LABELS"],"review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}},{"code":"TT-DIEN-SAN-01","ruleCode":"TT-DIEN-SAN","column":1,"title":"Không","tableLabel":"Không","contentHeading":"Không","content":"Theo đoạn chữ Không, ruộng đất cha mẹ cho có thể không giữ được; sau khi sa sút mới tự lo mua tạo ít nhiều để mở dựng lại.","textKind":"EDITORIAL_PARAPHRASE","sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","tableSource":{"book":"TT","pdfPages":[49],"printedPages":[50]},"contentSource":{"book":"TT","pdfPages":[49],"printedPages":[50]},"decisionIds":["DEC-20261026-M01-DIEN-SAN-REFERENCE"],"review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}},{"code":"TT-DIEN-SAN-02","ruleCode":"TT-DIEN-SAN","column":2,"title":"Bại","tableLabel":"Bại","contentHeading":"Bại","content":"Theo đoạn chữ Bại, điền sản cha mẹ cho hay tự tạo tại quê sinh dễ thất bại; có ý chí đi nơi khác lập điền viên thì được chút ít.","textKind":"EDITORIAL_PARAPHRASE","sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","tableSource":{"book":"TT","pdfPages":[49],"printedPages":[50]},"contentSource":{"book":"TT","pdfPages":[49],"printedPages":[50]},"decisionIds":["DEC-20261026-M01-DIEN-SAN-REFERENCE"],"review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}},{"code":"TT-DIEN-SAN-03","ruleCode":"TT-DIEN-SAN","column":3,"title":"Hướng","tableLabel":"Hướng","contentHeading":"Hướng","content":"Theo đoạn chữ Hướng, sách mô tả không chú trọng gìn giữ hay tạo lập ruộng đất, thiên về ăn mặc và vui chơi nên khó giữ điền sản.","textKind":"EDITORIAL_PARAPHRASE","sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","tableSource":{"book":"TT","pdfPages":[49],"printedPages":[50]},"contentSource":{"book":"TT","pdfPages":[50],"printedPages":[51]},"decisionIds":["DEC-20261026-M01-DIEN-SAN-REFERENCE"],"review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}},{"code":"TT-DIEN-SAN-04","ruleCode":"TT-DIEN-SAN","column":4,"title":"Kiên","tableLabel":"Kiên","contentHeading":"Kiên","content":"Theo đoạn chữ Kiên, ruộng đất cha mẹ cho hoặc tự tay tạo có thể được gìn giữ và phát triển thịnh vượng; nghề nông được luận là bền vững, thường gặp mùa thuận.","textKind":"EDITORIAL_PARAPHRASE","sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","tableSource":{"book":"TT","pdfPages":[49],"printedPages":[50]},"contentSource":{"book":"TT","pdfPages":[50],"printedPages":[51]},"decisionIds":["DEC-20261026-M01-DIEN-SAN-REFERENCE"],"review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}},{"code":"TT-DIEN-SAN-05","ruleCode":"TT-DIEN-SAN","column":5,"title":"Giải","tableLabel":"Giải","contentHeading":"Giải","content":"Theo đoạn chữ Giải, điền sản cha mẹ cho không giữ lâu, nhưng có thể tự tay tạo lập lại từ tay trắng và thịnh vượng lúc tuổi già.","textKind":"EDITORIAL_PARAPHRASE","sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","tableSource":{"book":"TT","pdfPages":[49],"printedPages":[50]},"contentSource":{"book":"TT","pdfPages":[50],"printedPages":[51]},"decisionIds":["DEC-20261026-M01-DIEN-SAN-REFERENCE"],"review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}},{"code":"TT-DIEN-SAN-06","ruleCode":"TT-DIEN-SAN","column":6,"title":"Phú / Phá","tableLabel":"Phú","contentHeading":"Phá","content":"Đoạn chữ Phá luận theo chiều không giữ được ruộng đất cha mẹ cho, đi nơi khác tạo lập lại cũng khó thành. Bảng in ghi Phú; liên kết đoạn Phá là quyết định biên tập theo cột thứ sáu.","textKind":"EDITORIAL_PARAPHRASE","sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","tableSource":{"book":"TT","pdfPages":[49],"printedPages":[50]},"contentSource":{"book":"TT","pdfPages":[50],"printedPages":[51]},"decisionIds":["DEC-20261026-M01-DIEN-SAN-REFERENCE","DEC-20261026-M01-DIEN-SAN-LABELS"],"review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}},{"code":"TT-DIEN-SAN-07","ruleCode":"TT-DIEN-SAN","column":7,"title":"Hiệp","tableLabel":"Hiệp","contentHeading":"Hiệp","content":"Theo đoạn chữ Hiệp, điền sản cha mẹ cho có thể được giữ và mua tạo thêm; sách luận theo chiều điền địa thịnh vượng, vững bền.","textKind":"EDITORIAL_PARAPHRASE","sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","tableSource":{"book":"TT","pdfPages":[49],"printedPages":[50]},"contentSource":{"book":"TT","pdfPages":[50],"printedPages":[51]},"decisionIds":["DEC-20261026-M01-DIEN-SAN-REFERENCE"],"review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}}],"tamTheMappings":[{"ruleCode":"TT-SANG-HEN","lookupKey":"BRANCH:TY|MONTH: