INSERT INTO expected_tam_the_supplement_results VALUES ('TT-SANG-HEN-01','M01-READINGS-20261026-V1','TT-SANG-HEN',1,'Nhựt Mã','Nhựt mã','Nhựt Mã','Theo đoạn Nhựt Mã, sách mô tả người hay đi lại, làm ăn khá, có điền địa và tài lợi; ở nhà ít lo, ra ngoài được đối đãi trọng hậu.','EDITORIAL_PARAPHRASE',(SELECT id FROM source_books WHERE file_sha256='7976f690145cc0bbdf6cb1bf2a0276b843512d231dca9a9f83b6f99820816c7d'),'{"code":"TT-SANG-HEN-01","ruleCode":"TT-SANG-HEN","column":1,"title":"Nhựt Mã","tableLabel":"Nhựt mã","contentHeading":"Nhựt Mã","content":"Theo đoạn Nhựt Mã, sách mô tả người hay đi lại, làm ăn khá, có điền địa và tài lợi; ở nhà ít lo, ra ngoài được đối đãi trọng hậu.","textKind":"EDITORIAL_PARAPHRASE","sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","tableSource":{"book":"TT","pdfPages":[43],"printedPages":[44]},"contentSource":{"book":"TT","pdfPages":[43],"printedPages":[44]},"decisionIds":[],"review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}}'::jsonb);
INSERT INTO expected_tam_the_supplement_results VALUES ('TT-SANG-HEN-02','M01-READINGS-20261026-V1','TT-SANG-HEN',2,'Lục Hại','Lục hại','Lục Hại','Theo đoạn Lục Hại, sách mô tả sự xung khắc với cha mẹ, anh em, họ hàng và vợ chồng con cái; đồng thời nêu hướng tu hành.','EDITORIAL_PARAPHRASE',(SELECT id FROM source_books WHERE file_sha256='7976f690145cc0bbdf6cb1bf2a0276b843512d231dca9a9f83b6f99820816c7d'),'{"code":"TT-SANG-HEN-02","ruleCode":"TT-SANG-HEN","column":2,"title":"Lục Hại","tableLabel":"Lục hại","contentHeading":"Lục Hại","content":"Theo đoạn Lục Hại, sách mô tả sự xung khắc với cha mẹ, anh em, họ hàng và vợ chồng con cái; đồng thời nêu hướng tu hành.","textKind":"EDITORIAL_PARAPHRASE","sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","tableSource":{"book":"TT","pdfPages":[43],"printedPages":[44]},"contentSource":{"book":"TT","pdfPages":[43],"printedPages":[44]},"decisionIds":[],"review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}}'::jsonb);
INSERT INTO expected_tam_the_supplement_results VALUES ('TT-SANG-HEN-03','M01-READINGS-20261026-V1','TT-SANG-HEN',3,'Hoa cái / Hao Cái','Hoa cái','Hao Cái','Đoạn mang tiêu đề Hao Cái mô tả người có duyên, được nhiều người thương và kính trọng, có tài giỏi và lộc thực. Bản diễn giải không suy đoán token khó hiểu trong câu in.','EDITORIAL_PARAPHRASE',(SELECT id FROM source_books WHERE file_sha256='7976f690145cc0bbdf6cb1bf2a0276b843512d231dca9a9f83b6f99820816c7d'),'{"code":"TT-SANG-HEN-03","ruleCode":"TT-SANG-HEN","column":3,"title":"Hoa cái / Hao Cái","tableLabel":"Hoa cái","contentHeading":"Hao Cái","content":"Đoạn mang tiêu đề Hao Cái mô tả người có duyên, được nhiều người thương và kính trọng, có tài giỏi và lộc thực. Bản diễn giải không suy đoán token khó hiểu trong câu in.","textKind":"EDITORIAL_PARAPHRASE","sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","tableSource":{"book":"TT","pdfPages":[43],"printedPages":[44]},"contentSource":{"book":"TT","pdfPages":[44],"printedPages":[45]},"decisionIds":["DEC-20261026-M01-SANG-HEN-LABELS"],"review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}}'::jsonb);
INSERT INTO expected_tam_the_supplement_results VALUES ('TT-SANG-HEN-04','M01-READINGS-20261026-V1','TT-SANG-HEN',4,'Kiếp Sát','Kiếp sát','Kiếp Sát','Theo đoạn Kiếp Sát, sách mô tả sự xung khắc trong gia đình, hoàn cảnh có thể sa sút; đoạn còn nêu phụ nữ thay đổi hôn nhân. Đây là mô tả trong nguồn cổ, không phải sự kiện đã được xác định cho người dùng.','EDITORIAL_PARAPHRASE',(SELECT id FROM source_books WHERE file_sha256='7976f690145cc0bbdf6cb1bf2a0276b843512d231dca9a9f83b6f99820816c7d'),'{"code":"TT-SANG-HEN-04","ruleCode":"TT-SANG-HEN","column":4,"title":"Kiếp Sát","tableLabel":"Kiếp sát","contentHeading":"Kiếp Sát","content":"Theo đoạn Kiếp Sát, sách mô tả sự xung khắc trong gia đình, hoàn cảnh có thể sa sút; đoạn còn nêu phụ nữ thay đổi hôn nhân. Đây là mô tả trong nguồn cổ, không phải sự kiện đã được xác định cho người dùng.","textKind":"EDITORIAL_PARAPHRASE","sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","tableSource":{"book":"TT","pdfPages":[43],"printedPages":[44]},"contentSource":{"book":"TT","pdfPages":[44],"printedPages":[45]},"decisionIds":[],"review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}}'::jsonb);
INSERT INTO expected_tam_the_supplement_results VALUES ('TT-SANG-HEN-05','M01-READINGS-20261026-V1','TT-SANG-HEN',5,'Tai Sát','Tai sát','Tai Sát','Theo đoạn Tai Sát, sách nêu tật bệnh, tai nạn và xung khắc vợ chồng, con cái. Nội dung được trình bày như quan niệm trong sách, không dùng để chẩn đoán bệnh hay xác nhận tai nạn.','EDITORIAL_PARAPHRASE',(SELECT id FROM source_books WHERE file_sha256='7976f690145cc0bbdf6cb1bf2a0276b843512d231dca9a9f83b6f99820816c7d'),'{"code":"TT-SANG-HEN-05","ruleCode":"TT-SANG-HEN","column":5,"title":"Tai Sát","tableLabel":"Tai sát","contentHeading":"Tai Sát","content":"Theo đoạn Tai Sát, sách nêu tật bệnh, tai nạn và xung khắc vợ chồng, con cái. Nội dung được trình bày như quan niệm trong sách, không dùng để chẩn đoán bệnh hay xác nhận tai nạn.","textKind":"EDITORIAL_PARAPHRASE","sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","tableSource":{"book":"TT","pdfPages":[43],"printedPages":[44]},"contentSource":{"book":"TT","pdfPages":[44],"printedPages":[45]},"decisionIds":[],"review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}}'::jsonb);
INSERT INTO expected_tam_the_supplement_results VALUES ('TT-SANG-HEN-06','M01-READINGS-20261026-V1','TT-SANG-HEN',6,'Thiên Sát','Thiên sát','Thiên Sát','Theo đoạn Thiên Sát, sách nêu xung khắc với gia đình bên vợ hoặc bên chồng, ít con, bệnh nặng hay cảnh lưu lạc tự tìm sinh kế. Các mô tả này thuộc lời luận của nguồn cổ.','EDITORIAL_PARAPHRASE',(SELECT id FROM source_books WHERE file_sha256='7976f690145cc0bbdf6cb1bf2a0276b843512d231dca9a9f83b6f99820816c7d'),'{"code":"TT-SANG-HEN-06","ruleCode":"TT-SANG-HEN","column":6,"title":"Thiên Sát","tableLabel":"Thiên sát","contentHeading":"Thiên Sát","content":"Theo đoạn Thiên Sát, sách nêu xung khắc với gia đình bên vợ hoặc bên chồng, ít con, bệnh nặng hay cảnh lưu lạc tự tìm sinh kế. Các mô tả này thuộc lời luận của nguồn cổ.","textKind":"EDITORIAL_PARAPHRASE","sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","tableSource":{"book":"TT","pdfPages":[43],"printedPages":[44]},"contentSource":{"book":"TT","pdfPages":[44],"printedPages":[45]},"decisionIds":[],"review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}}'::jsonb);
INSERT INTO expected_tam_the_supplement_results VALUES ('TT-SANG-HEN-07','M01-READINGS-20261026-V1','TT-SANG-HEN',7,'Địa Sát','Địa sát','Địa Sát','Theo đoạn Địa Sát, sách đồng thời nêu tai nạn, xung khắc trong gia đình và khả năng có nghề giỏi, làm ăn no đủ. Hai chiều nội dung được giữ cùng nhau.','EDITORIAL_PARAPHRASE',(SELECT id FROM source_books WHERE file_sha256='7976f690145cc0bbdf6cb1bf2a0276b843512d231dca9a9f83b6f99820816c7d'),'{"code":"TT-SANG-HEN-07","ruleCode":"TT-SANG-HEN","column":7,"title":"Địa Sát","tableLabel":"Địa sát","contentHeading":"Địa Sát","content":"Theo đoạn Địa Sát, sách đồng thời nêu tai nạn, xung khắc trong gia đình và khả năng có nghề giỏi, làm ăn no đủ. Hai chiều nội dung được giữ cùng nhau.","textKind":"EDITORIAL_PARAPHRASE","sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","tableSource":{"book":"TT","pdfPages":[43],"printedPages":[44]},"contentSource":{"book":"TT","pdfPages":[44],"printedPages":[45]},"decisionIds":[],"review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}}'::jsonb);
INSERT INTO expected_tam_the_supplement_results VALUES ('TT-SANG-HEN-08','M01-READINGS-20261026-V1','TT-SANG-HEN',8,'Niên Sát','Niên sát','Niên Sát','Theo đoạn Niên Sát, sách mô tả rời nơi cha mẹ đã lập để làm ăn nơi khác, tự tạo sự nghiệp, ít nhờ cậy anh em.','EDITORIAL_PARAPHRASE',(SELECT id FROM source_books WHERE file_sha256='7976f690145cc0bbdf6cb1bf2a0276b843512d231dca9a9f83b6f99820816c7d'),'{"code":"TT-SANG-HEN-08","ruleCode":"TT-SANG-HEN","column":8,"title":"Niên Sát","tableLabel":"Niên sát","contentHeading":"Niên Sát","content":"Theo đoạn Niên Sát, sách mô tả rời nơi cha mẹ đã lập để làm ăn nơi khác, tự tạo sự nghiệp, ít nhờ cậy anh em.","textKind":"EDITORIAL_PARAPHRASE","sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","tableSource":{"book":"TT","pdfPages":[43],"printedPages":[44]},"contentSource":{"book":"TT","pdfPages":[44],"printedPages":[45]},"decisionIds":[],"review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}}'::jsonb);
INSERT INTO expected_tam_the_supplement_results VALUES ('TT-SANG-HEN-09','M01-READINGS-20261026-V1','TT-SANG-HEN',9,'Ngoại Sát','Ngoại sát','Ngoại Sát','Theo đoạn Ngoại Sát, sách mô tả làm ăn khá khi đến nơi khác, từ tay trắng lập sự nghiệp; đồng thời có lời luận xung khắc vợ chồng và con cái.','EDITORIAL_PARAPHRASE',(SELECT id FROM source_books WHERE file_sha256='7976f690145cc0bbdf6cb1bf2a0276b843512d231dca9a9f83b6f99820816c7d'),'{"code":"TT-SANG-HEN-09","ruleCode":"TT-SANG-HEN","column":9,"title":"Ngoại Sát","tableLabel":"Ngoại sát","contentHeading":"Ngoại Sát","content":"Theo đoạn Ngoại Sát, sách mô tả làm ăn khá khi đến nơi khác, từ tay trắng lập sự nghiệp; đồng thời có lời luận xung khắc vợ chồng và con cái.","textKind":"EDITORIAL_PARAPHRASE","sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","tableSource":{"book":"TT","pdfPages":[43],"printedPages":[44]},"contentSource":{"book":"TT","pdfPages":[44],"printedPages":[45]},"decisionIds":[],"review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}}'::jsonb);
INSERT INTO expected_tam_the_supplement_results VALUES ('TT-SANG-HEN-10','M01-READINGS-20261026-V1','TT-SANG-HEN',10,'Vong sát / Vong Thần','Vong sát','Vong Thần','Đoạn Vong Thần mô tả xung khắc anh em, bà con; qua nhiều lần đổi chỗ ở mới lập sự nghiệp, điền viên tốt. Nhãn bảng vẫn được lưu là Vong sát.','EDITORIAL_PARAPHRASE',(SELECT id FROM source_books WHERE file_sha256='7976f690145cc0bbdf6cb1bf2a0276b843512d231dca9a9f83b6f99820816c7d'),'{"code":"TT-SANG-HEN-10","ruleCode":"TT-SANG-HEN","column":10,"title":"Vong sát / Vong Thần","tableLabel":"Vong sát","contentHeading":"Vong Thần","content":"Đoạn Vong Thần mô tả xung khắc anh em, bà con; qua nhiều lần đổi chỗ ở mới lập sự nghiệp, điền viên tốt. Nhãn bảng vẫn được lưu là Vong sát.","textKind":"EDITORIAL_PARAPHRASE","sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","tableSource":{"book":"TT","pdfPages":[43],"printedPages":[44]},"contentSource":{"book":"TT","pdfPages":[44],"printedPages":[45]},"decisionIds":["DEC-20261026-M01-SANG-HEN-LABELS"],"review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}}'::jsonb);
INSERT INTO expected_tam_the_supplement_results VALUES ('TT-SANG-HEN-11','M01-READINGS-20261026-V1','TT-SANG-HEN',11,'Tướng linh / Tướng Tinh','Tướng linh','Tướng Tinh','Đoạn Tướng Tinh mô tả người có quyền hành, phát tài và hưởng lộc từ sớm, gia đình con cháu sung túc. Bản diễn giải chỉ giữ phần chữ đọc rõ, không đoán cụm chữ mờ sau quyền hành.','EDITORIAL_PARAPHRASE',(SELECT id FROM source_books WHERE file_sha256='7976f690145cc0bbdf6cb1bf2a0276b843512d231dca9a9f83b6f99820816c7d'),'{"code":"TT-SANG-HEN-11","ruleCode":"TT-SANG-HEN","column":11,"title":"Tướng linh / Tướng Tinh","tableLabel":"Tướng linh","contentHeading":"Tướng Tinh","content":"Đoạn Tướng Tinh mô tả người có quyền hành, phát tài và hưởng lộc từ sớm, gia đình con cháu sung túc. Bản diễn giải chỉ giữ phần chữ đọc rõ, không đoán cụm chữ mờ sau quyền hành.","textKind":"EDITORIAL_PARAPHRASE","sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","tableSource":{"book":"TT","pdfPages":[43],"printedPages":[44]},"contentSource":{"book":"TT","pdfPages":[44],"printedPages":[45]},"decisionIds":["DEC-20261026-M01-SANG-HEN-LABELS"],"review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}}'::jsonb);
INSERT INTO expected_tam_the_supplement_results VALUES ('TT-SANG-HEN-12','M01-READINGS-20261026-V1','TT-SANG-HEN',12,'Thiên an / Phiên An','Thiên an','Phiên An','Đoạn có tiêu đề Phiên An nhưng phần thân gọi Thiên An, mô tả tính cương cường, thông minh, có hướng tu niệm và học hành khoa cử. Dự án bảo tồn cả hai nhãn.','EDITORIAL_PARAPHRASE',(SELECT id FROM source_books WHERE file_sha256='7976f690145cc0bbdf6cb1bf2a0276b843512d231dca9a9f83b6f99820816c7d'),'{"code":"TT-SANG-HEN-12","ruleCode":"TT-SANG-HEN","column":12,"title":"Thiên an / Phiên An","tableLabel":"Thiên an","contentHeading":"Phiên An","content":"Đoạn có tiêu đề Phiên An nhưng phần thân gọi Thiên An, mô tả tính cương cường, thông minh, có hướng tu niệm và học hành khoa cử. Dự án bảo tồn cả hai nhãn.","textKind":"EDITORIAL_PARAPHRASE","sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","tableSource":{"book":"TT","pdfPages":[43],"printedPages":[44]},"contentSource":{"book":"TT","pdfPages":[44],"printedPages":[45]},"decisionIds":["DEC-20261026-M01-SANG-HEN-LABELS"],"review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}}'::jsonb);
INSERT INTO expected_tam_the_supplement_results VALUES ('TT-DIEN-SAN-01','M01-READINGS-20261026-V1','TT-DIEN-SAN',1,'Không','Không','Không','Theo đoạn chữ Không, ruộng đất cha mẹ cho có thể không giữ được; sau khi sa sút mới tự lo mua tạo ít nhiều để mở dựng lại.','EDITORIAL_PARAPHRASE',(SELECT id FROM source_books WHERE file_sha256='7976f690145cc0bbdf6cb1bf2a0276b843512d231dca9a9f83b6f99820816c7d'),'{"code":"TT-DIEN-SAN-01","ruleCode":"TT-DIEN-SAN","column":1,"title":"Không","tableLabel":"Không","contentHeading":"Không","content":"Theo đoạn chữ Không, ruộng đất cha mẹ cho có thể không giữ được; sau khi sa sút mới tự lo mua tạo ít nhiều để mở dựng lại.","textKind":"EDITORIAL_PARAPHRASE","sourceStatus":"VERIFIED","basis":"SOURCE_VERIFIED","tableSource":{"book":"TT","pdfPages":[49],"printedPages":[50]},"contentSource":{"book":"TT","pdfPages":[49],"printedPages":[50]},"decisionIds":["DEC-20261026-M01-DIEN-SAN-REFERENCE"],"review":{"editor":"Codex M01 transcription 2026-10-26","reviewer":"Codex M01 second visual pass 2026-10-26 (same tool; not independent human)","reviewedAt":"2026-10-25T18:23:10Z","method":"SAME_TOOL_TWO_VISUAL_PASSES","independentHumanReview":false}}'::jsonb);
